/// Returns a new vector where each element is the absolute value of the
/// corresponding input element, preserving order.
///
/// Assumptions from the problem:
/// - `x.len() < 1_000_000`
/// - No element of `x` equals `i32::MIN` (so absolute value fits in `i32`)
pub fn absx(x: Vec<i32>) -> Vec<i32> {
    let mut y = Vec::with_capacity(x.len());

    for v in x {
        // Widen to i64 to avoid overflow on negation/abs in i32.
        // Given v != i32::MIN, (v as i64).abs() always fits back into i32.
        let a = (v as i64).abs() as i32;
        y.push(a);
    }

    y
}

